static <T, R> void subscribeConcatMapDelayError(ObservableConcatMap.ConcatMapDelayErrorObserver<T, R> o, Disposable d) {
    if (DisposableHelper.validate(o.upstream, d)) {
        o.upstream = d;
        if (d instanceof QueueDisposable) {
            @SuppressWarnings("unchecked")
            QueueDisposable<T> qd = (QueueDisposable<T>) d;
            int m = qd.requestFusion(QueueDisposable.ANY);
            if (m == QueueDisposable.SYNC) {
                o.sourceMode = m;
                o.queue = qd;
                o.done = true;
                o.downstream.onSubscribe(o);
                drainConcatMapDelayError(o);
                return;
            }
            if (m == QueueDisposable.ASYNC) {
                o.sourceMode = m;
                o.queue = qd;
                o.downstream.onSubscribe(o);
                return;
            }
        }
        o.queue = new SpscLinkedArrayQueue<>(o.bufferSize);
        o.downstream.onSubscribe(o);
    }
}


static <T, U> void innerCompleteConcatMap(ObservableConcatMap.SourceObserver<T, U> o) {
    o.active = false;
    drainConcatMap(o);
}

static <T, R> void onNextConcatMapDelayErrorInner(
        ObservableConcatMap.ConcatMapDelayErrorObserver<T, R> parent, R value) {
    parent.downstream.onNext(value);
}

static <T, R> void onErrorConcatMapDelayErrorInner(
        ObservableConcatMap.ConcatMapDelayErrorObserver<T, R> parent, Throwable e) {
    if (parent.errors.tryAddThrowableOrReport(e)) {
        if (!parent.tillTheEnd) {
            parent.upstream.dispose();
        }
        parent.active = false;
        drainConcatMapDelayError(parent);
    }
}

static <T, R> void onCompleteConcatMapDelayErrorInner(
        ObservableConcatMap.ConcatMapDelayErrorObserver<T, R> parent) {
    parent.active = false;
    drainConcatMapDelayError(parent);
}

